import "./image.css";

export interface ImageProps {
  src: string;
  alt: string;
  width: "contained" | "full bleed";
  ratio: "16 / 9" | "4 / 3" | "1 / 1" | "3 / 2" | "21 / 9";
  fit: "cover" | "contain" | "fill";
  position: "center" | "top" | "bottom" | "left" | "right";
  radius: "none" | "soft" | "round";
  treatment: "color" | "b&w";
}

export function ImageRender({ src, alt, width, ratio, fit, position, radius, treatment }: ImageProps) {
  const full = width === "full bleed";
  return (
    <div className="p1-image" data-width={width}>
      <div
        className="p1-image__wrap"
        data-radius={!full ? radius : undefined}
        style={{ aspectRatio: ratio }}
      >
        <img
          src={src}
          alt={alt}
          className="p1-image__img"
          data-treatment={treatment}
          style={{ objectFit: fit, objectPosition: position }}
        />
      </div>
    </div>
  );
}

import type { ComponentConfig } from "@puckeditor/core";
import { defineMeta, wireframe } from '../define-meta';
import { ImageRender, type ImageProps } from "./image";
export type { ImageProps };

export const ImageBlock: ComponentConfig<ImageProps> = {
  fields: {
    src: {
      type: "text" as const,
      ai: { exclude: true },
    },
    alt: {
      type: "text" as const,
      ai: { instructions: "Concise alt text describing what's in the image. Screen reader users depend on this." },
    },
    width: {
      type: "radio" as const,
      options: [
        { label: "Contained", value: "contained" },
        { label: "Full bleed", value: "full bleed" },
      ],
    },
    ratio: {
      type: "select" as const,
      options: [
        { label: "16 / 9", value: "16 / 9" },
        { label: "4 / 3", value: "4 / 3" },
        { label: "1 / 1", value: "1 / 1" },
        { label: "3 / 2", value: "3 / 2" },
        { label: "21 / 9", value: "21 / 9" },
      ],
    },
    fit: {
      type: "select" as const,
      options: [
        { label: "Cover", value: "cover" },
        { label: "Contain", value: "contain" },
        { label: "Fill", value: "fill" },
      ],
    },
    position: {
      type: "select" as const,
      options: [
        { label: "Center", value: "center" },
        { label: "Top", value: "top" },
        { label: "Bottom", value: "bottom" },
        { label: "Left", value: "left" },
        { label: "Right", value: "right" },
      ],
    },
    radius: {
      type: "select" as const,
      options: [
        { label: "None", value: "none" },
        { label: "Soft", value: "soft" },
        { label: "Round", value: "round" },
      ],
    },
    treatment: {
      type: "radio" as const,
      options: [
        { label: "Color", value: "color" },
        { label: "B&W", value: "b&w" },
      ],
    },
  },
  defaultProps: {
    src: wireframe(1100, 619),
    alt: "Editorial photograph",
    width: "contained",
    ratio: "16 / 9",
    fit: "cover",
    position: "center",
    radius: "soft",
    treatment: "color",
  },
  render: ImageRender,
};

export const meta = defineMeta({
  title: 'Image',
  description: 'Simple full-bleed or contained image block with aspect ratio, fit, position, radius, and b&w treatment controls; use for standalone images.',
  categories: ["showcase"],
  published: true,
});

.p1-image { margin-inline: auto; }

/* Contained: page gutters + max-width */
.p1-image[data-width="contained"] {
  max-inline-size: var(--p1-container-wide);
  padding-block: var(--p1-space-md);
  padding-inline: var(--p1-space-lg);
}

.p1-image__wrap {
  background-color: var(--p1-surface-subtle);
  overflow: hidden;
}

/* Contained-only decorations */
.p1-image[data-width="contained"] .p1-image__wrap {
  border: 1px solid var(--p1-border);
}

.p1-image__wrap[data-radius="soft"]  { border-radius: var(--p1-radius-card); }
.p1-image__wrap[data-radius="round"] { border-radius: var(--p1-radius-xl); }

.p1-image__img {
  block-size: 100%;
  display: block;
  inline-size: 100%;
}

.p1-image__img[data-treatment="b&w"] { filter: grayscale(1); }

